insert into public.books
  (id, title, subtitle, eyebrow, author, price, description, quote, cover, cover_class, category, pages, sort_order)
values
  ('playing', 'Playing with Meditation', '59 playful meditations for kids of all ages', 'MINDFULNESS · FAMILY EDITION', 'Sw. Nirav Jayant', 500, '59 playful meditations created for curious children of every age—and the grown-ups who want to slow down with them.', '“Make a little room for wonder, and stillness arrives on its own.”', '/books/playing-with-meditation.png', 'cover-playing', 'kids', '[["A small pause","Sit comfortably. Notice three sounds nearby, then three sounds far away. There is nothing to fix—only something new to hear."],["The sun breath","Stretch your arms out wide as you breathe in. Bring your hands to your heart as you breathe out. Repeat slowly, like sunrise."],["A pocket of calm","Imagine carrying a quiet garden in your pocket. What grows there? Visit it whenever the day feels too loud."]]'::jsonb, 1),
  ('zenful', 'Zenful Stories', 'Everyday wisdom from ancient Zen masters', 'WISDOM · DIGITAL EDITION', 'Sw. Nirav Jayant', 599, 'Everyday wisdom from ancient Zen masters. A thoughtful companion for building a quieter, more conscious everyday practice.', '“A gentle invitation to pause, soften, and meet this moment exactly as it is.”', '/books/zenful-stories.png', 'cover-zenful', 'meditation', '[["The empty cup","A scholar came to learn about Zen. The master poured tea until the cup overflowed. “Like this cup,” he said, “you are full of ideas.”"],["Just this step","The path is not waiting at the end of the journey. It is beneath your feet, whole and complete, in this single step."],["The sound of rain","When rain comes, listen without naming it. For one quiet minute, let the world arrive before your thoughts do."]]'::jsonb, 2),
  ('breath', 'Playing with Breath', '64 fun breathing games for kids', 'BREATHWORK · FOR KIDS', 'Sw. Nirav Jayant', 500, '64 fun breathing games for kids—simple, playful ways to calm big feelings, find focus, and enjoy the magic of a single breath.', '“Every breath is a little game you can always play.”', '/books/playing-with-breath.jpg', 'cover-breath', 'kids', '[["Dandelion wish","Hold an imaginary dandelion. Breathe in slowly through your nose, then blow out gently and watch the seeds float away."],["Balloon belly","Place your hands on your tummy. Breathe in and let it grow round like a balloon. Breathe out and let it softly shrink."],["Bumblebee hum","Close your eyes and breathe in. As you breathe out, hum like a bee. Feel the tiny buzz in your face and chest."]]'::jsonb, 3),
  ('meditation-365', 'Meditation 365', '365 simple daily meditations for everyday life', 'DAILY PRACTICE · YEAR-ROUND', 'Sw. Nirav Jayant', 699, 'Simple, easy-to-do daily meditations designed to fit into your everyday life—one for every day of the year.', '“A single quiet minute, repeated, becomes a different life.”', '/books/meditation-365.jpg', 'cover-365', 'meditation', '[["Day 1 · Arrive","Sit where you are. Feel the weight of your body resting down. Let this moment be the whole of your practice today."],["Day 2 · Count ten","Count ten slow breaths. If you lose count, smile and begin again at one. Beginning again is the practice."],["Day 3 · Morning light","Before reaching for your phone, look toward the light for three breaths. Let the day find you first."]]'::jsonb, 4),
  ('zenful-21', 'Zenful 21 Days', 'Small Zen meditation techniques for daily life', 'ZEN · 21-DAY JOURNEY', 'Sw. Nirav Jayant', 549, 'Small Zen meditation techniques for your daily life—a gentle 21-day journey into stillness, presence, and ease.', '“This very body the Buddha; this very earth the lotus paradise.”', '/books/zenful-21-days.png', 'cover-zenful-21', 'meditation', '[["Day 1 · Just sitting","Sit with nothing to achieve. When thoughts come, let them pass like clouds. You are the sky, not the weather."],["Day 2 · Walking slowly","Walk ten steps as slowly as you can. Feel the heel, the arch, the toes. Arrive fully with every step."],["Day 3 · One thing","Wash one cup with total attention. The warmth of water, the curve of the cup. This is meditation too."]]'::jsonb, 5),
  ('release-relax', 'Release and Relax', '30 somatic ways to release anger', 'SOMATIC · EMOTIONAL RELEASE', 'Sw. Nirav Jayant', 599, '30 simple yet powerful somatic ways to release anger—safely letting emotion move through the body so calm can return.', '“What we allow to move, moves on.”', '/books/release-and-relax.png', 'cover-release', 'meditation', '[["Shake it out","Stand and shake your hands, then your arms, then your whole body for one minute. Let the energy leave through your fingertips."],["The long exhale","Breathe in for four counts, out for eight. A longer exhale tells the body it is safe to soften."],["Press and release","Press your palms together hard for five breaths. Then let go completely and notice the warmth that follows."]]'::jsonb, 6),
  ('unwinding-anxiety', 'Unwinding Anxiety', '50 somatic ways to rewire your nervous system', 'SOMATIC · NERVOUS SYSTEM', 'Sw. Nirav Jayant', 599, '50 somatic ways to rewire your nervous system—gentle, body-based practices for easing anxiety and feeling safe again.', '“Calm is not something you think. It is something the body remembers.”', '/books/unwinding-anxiety.jpg', 'cover-anxiety', 'meditation', '[["Hand on heart","Place one hand on your heart and one on your belly. Feel the warmth. Breathe as if breathing into your hands."],["Five things","Name five things you can see, four you can touch, three you can hear. Let your senses bring you back."],["Butterfly hug","Cross your arms over your chest and tap your shoulders slowly, left then right. Let the rhythm settle you."]]'::jsonb, 7),
  ('somehow', 'Somehow', 'Art of living in the world of possibilities', 'ABUNDANCE · POSSIBILITY', 'Dr. Sw. Nirav Jayant', 649, 'The art of living in the world of possibilities—opening to abundance, trusting the unknown, and finding a way, somehow.', '“When you stop insisting on how, life begins to show you somehow.”', '/books/somehow.jpg', 'cover-somehow', 'abundance', '[["Open hands","Notice where you are gripping—your jaw, your plans, your expectations. Open your hands and let something new arrive."],["Already enough","Write down three things you already have that you once wished for. Abundance begins with noticing."],["The next small step","You do not need to see the whole road. Ask only: what is one small step I can take today?"]]'::jsonb, 8)
